import{_ as a,o as n,c as i,a3 as s}from"./chunks/framework.1Y430-yj.js";const g=JSON.parse('{"title":"Chubby Lung Factory Event Notes","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"龙泡泡基建活动相关事项","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=1cmRL9Ya06LDbO5jjC7IO1","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-1cmRL9Ya06LDbO5jjC7IO1.md","filePath":"logistics/src/page-1cmRL9Ya06LDbO5jjC7IO1.md","lastUpdated":null}'),r={name:"logistics/src/page-1cmRL9Ya06LDbO5jjC7IO1.md"};function t(o,e,p,u,l,c){return n(),i("div",null,[...e[0]||(e[0]=[s('<div class="logistics-content"><span class="logistics-source-anchor" id="龙泡泡基建活动相关事项" aria-hidden="true"></span><h1 id="chubby-lung-factory-event-notes" tabindex="-1">Chubby Lung Factory Event Notes <a class="header-anchor" href="#chubby-lung-factory-event-notes" aria-label="Permalink to &quot;Chubby Lung Factory Event Notes&quot;">​</a></h1><blockquote><p>Source page ID: <code>1cmRL9Ya06LDbO5jjC7IO1</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=1cmRL9Ya06LDbO5jjC7IO1" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span class="mark-blue">You do not need to make small Chubby Lungs to unlock the large ones!</span></p><p><span id="source-block-7e8C3Zzko6WKfXPxBCBf8j"></span></p><span class="logistics-source-anchor" id="数据汇总" aria-hidden="true"></span><h2 id="data-summary" tabindex="-1">Data Summary <a class="header-anchor" href="#data-summary" aria-label="Permalink to &quot;Data Summary&quot;">​</a></h2><p><a href="./page-B6p5P8ptZmUGDgDRCVTZdJ">AIC Information from Previews</a></p><p><span id="source-block-6Sj9AUEZFFAsbRczpICbbP"></span></p><span class="logistics-source-anchor" id="配方" aria-hidden="true"></span><h2 id="recipes" tabindex="-1">Recipes <a class="header-anchor" href="#recipes" aria-label="Permalink to &quot;Recipes&quot;">​</a></h2><p><span id="source-block-vgo5MejFCuh7TN7RM6wSHH"></span></p><span class="logistics-source-anchor" id="原始配方" aria-hidden="true"></span><h4 id="original-recipes" tabindex="-1">Original Recipes <a class="header-anchor" href="#original-recipes" aria-label="Permalink to &quot;Original Recipes&quot;">​</a></h4><p>1 Xiranite = 1 Proto Xiranite (Refining Unit, 2s)</p><p>1 Proto Xiranite = 1 Proto Chubby Lung Shell (Moulding Unit, 2s)</p><p>4 Cuprium Part + 1 Xiranite = 1 Proto Cuprium Frame (Packaging Unit, 2s)</p><p>5 Proto Chubby Lung Shell + 5 Proto Cuprium Frame = 1 Xiranite Chubby Lung (Packaging Unit, 10s)</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-5cf756bf75d5dc98.q90-beb351b6975f0822.webp" alt="Chubby Lung Factory Event Notes"></p><hr><p>1 Heavy Xiranite = 1 Proto Heavy Xiranite (Refining Unit, 10s)</p><p>1 Proto Heavy Xiranite + 5 Inergen = 1 Proto Chubby Lung Heavy Shell (Moulding Unit, 10s)</p><p>2 Cuprium Gas + 1 Xiragen = 1 Proto Xiran-Cuprium Gas (Gas Reactor Globe, 2s)</p><p>1 Proto Xiran-Cuprium Gas = 1 Proto Xiran-Cuprium (Solid-Gas Transmuting Unit, 2s)</p><p>5 Proto Xiran-Cuprium = 1 Proto Xiran-Cuprium Part (Fitting Unit, 10s)</p><p>1 Proto Xiran-Cuprium Part + 1 Heavy Xiranite = 1 Proto Xiran-Cuprium Frame (Packaging Unit, 10s)</p><p>1 Proto Chubby Lung Heavy Shell + 1 Proto Xiran-Cuprium Frame = 1 Heavy Xiranite Chubby Lung (Packaging Unit, 10s)</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-e9c26224aa0cf35e.q90-5027f8a60a5a5bb1.webp" alt="Chubby Lung Factory Event Notes"></p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-5e2151617917471d.q90-c1dbb6bf0b9a65d3.webp" alt="Chubby Lung Factory Event Notes"></p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-de18758df159c540.q90-c0e22dbcd0bf5e4f.webp" alt="Chubby Lung Factory Event Notes"></p><p><span id="source-block-iWRGnAIK07Gn9EQZ6TC3kW"></span></p><span class="logistics-source-anchor" id="整理后配方" aria-hidden="true"></span><h4 id="consolidated-recipes" tabindex="-1">Consolidated Recipes <a class="header-anchor" href="#consolidated-recipes" aria-label="Permalink to &quot;Consolidated Recipes&quot;">​</a></h4><p>1 Xiranite Chubby Lung = 20 Cuprium + 10 Xiranite</p><p>1 Heavy Xiranite Chubby Lung = 10 Cuprium Gas + 6 Xiragen + 2 Heavy Xiranite + 5 Inergen</p><p>= 20 Cuprium + 9.2 Xiranite + 2 Heavy Xiranite + 5 Inergen (liquid–gas route; 9.6 Xiranite if Cuprium uses solid–gas, 10 Xiranite if both use solid–gas).</p><p>Single-core Heavy Xiranite Chubby Lung, 6/m = 120 Cuprium + 55.2 Xiranite + 12 Heavy Xiranite + 30 Inergen per minute.</p><p>Inputs per Chubby Lung: 20 Cuprium, 10 Xiranite, value 100; 25 Cuprium, 24.9 Xiranite, 7.5 Inergen, value 200.</p><p><span id="source-block-BeJgoP86Dz7Q1PtXpT6hm7"></span></p><span class="logistics-source-anchor" id="据点产值和售价" aria-hidden="true"></span><h3 id="outpost-output-value-and-selling-prices" tabindex="-1">Outpost Output Value and Selling Prices <a class="header-anchor" href="#outpost-output-value-and-selling-prices" aria-label="Permalink to &quot;Outpost Output Value and Selling Prices&quot;">​</a></h3><p>Large Chubby Lung: 200 Stock Bills + 20 aid certificates.</p><p>Small Chubby Lung: 100 Stock Bills + 10 aid certificates.</p><p>Pyrrolite Part, 70 = 25 Cuprium + 11.8 Xiranite (liquid–gas, two-core Pyrrolite; four-core uses 11.75 Xiranite).</p><p>Hetonite Part, 48 = 25 Cuprium + 5.7 Xiranite (liquid–gas).</p><p>Heavy Xiranite, 27 = 2.5 Cuprium + 7.85 Xiranite (liquid–gas).</p><p>Cuprium-based medicine, 22 = 20 Cuprium.</p><p>Hourly outpost output value: level-4 Sky King Flats 42000 + level-4 Cardiac Remediation Station 27360 + level-4 Xiranflow Cloudseeder 33600 = 102960, or 1716 per minute.</p><p>Base accumulation rates are respectively 30000, 22800, and 24000: total 76800/h = 1280/m.</p><p>The voucher-output multiplier bonus is 0.25 in each phase: phase one 0.25, phase two 0.5, calculated cumulatively.</p><p><strong>After a 25% boost: 1716+1280*0.25=2036 per minute.</strong></p><p><strong>After a 50% boost: 1716+1280*0.5=2356 per minute.</strong></p><p><span id="source-block-QXCjpc23yJHwd8F6sM0A8p"></span></p><span class="logistics-source-anchor" id="其他相关数据" aria-hidden="true"></span><h3 id="other-relevant-data" tabindex="-1">Other Relevant Data <a class="header-anchor" href="#other-relevant-data" aria-label="Permalink to &quot;Other Relevant Data&quot;">​</a></h3><p><span id="source-block-hMWr1YFKh1dwaMFy15t1FG"></span></p><span class="logistics-source-anchor" id="活动开启时间" aria-hidden="true"></span><h4 id="event-opening-times" tabindex="-1">Event Opening Times <a class="header-anchor" href="#event-opening-times" aria-label="Permalink to &quot;Event Opening Times&quot;">​</a></h4><p>2026/9/16 12:00:00: phase one.</p><p>2026/9/23 4:00:00: phase two.</p><p>2026/9/30 16:00:00: event recipes close.</p><p>2026/10/7 4:00:00: shop closes.</p><p>Phase one lasts 6 days 16 hours = 160 hours = <strong>9600 minutes</strong>; phase two lasts 7 days 12 hours = 180 hours = <strong>10800 minutes</strong>.</p><p><span id="source-block-7ezBftIvbb1FuDyNaZDYST"></span></p><span class="logistics-source-anchor" id="活动商店援助券价格" aria-hidden="true"></span><h4 id="event-shop-prices-in-aid-certificates" tabindex="-1">Event Shop Prices in Aid Certificates <a class="header-anchor" href="#event-shop-prices-in-aid-certificates" aria-label="Permalink to &quot;Event Shop Prices in Aid Certificates&quot;">​</a></h4><p><a href="./page-MRWxeGp6rLBPnHWgYBFAX8">Shop Contents</a></p><details><summary>Etched Medal</summary><p>Etched medal<br> Chubby Lung Explosion<br> The great Chubby Lung leaves its footprints across the land. Attack, attack!<br> Earn a cumulative 800000 Fruits of Altruism Certs during “Integrated Aid: Chubby Lung, Attack!”<br> Earn a cumulative 800000 Fruits of Altruism Certs and submit a cumulative 20000 Heavy Xiranite Chubby Lung during “Integrated Aid: Chubby Lung, Attack!”</p></details><p><span id="source-block-01lA8uksMqSOaDfGa5DAIc"></span></p><span class="logistics-source-anchor" id="价值分析与生产方案" aria-hidden="true"></span><h2 id="value-analysis-and-production-plans" tabindex="-1">Value Analysis and Production Plans <a class="header-anchor" href="#value-analysis-and-production-plans" aria-label="Permalink to &quot;Value Analysis and Production Plans&quot;">​</a></h2><p><span id="source-block-e18QBofdmV4q2fGlExA2mN"></span></p><span class="logistics-source-anchor" id="生产方案" aria-hidden="true"></span><h3 id="production-plans" tabindex="-1">Production Plans <a class="header-anchor" href="#production-plans" aria-label="Permalink to &quot;Production Plans&quot;">​</a></h3><p><span class="mark-red">Plan 1:</span></p><p>Simplest plan: in phase one, make any small amount on one small Chubby Lung line to unlock phase-two Chubby Lung. In phase two, build two full-rate large Chubby Lung lines. Even if completed a day after phase two begins, phase two provides 20<em>12</em>60<em>24</em>6.5=2246400 event certificates, easily enough to clear the shop.</p><p>Alternatively, two small Chubby Lung lines: 2,180,800÷10÷12÷60÷24&lt;13 days. Even starting almost halfway through phase one is in time.</p><p><span class="mark-red">Plan 2:</span> (Clear the shop and obtain the medal trim.)</p><p>On top of the original line, phase one must produce 411400/10=<strong>41140</strong> <span class="mark-green">Xiranite Chubby Lung</span>, or <strong>4.285</strong>/min. Phase two must still produce 1769400/20=<strong>88470</strong> <span class="mark-sky_blue">Heavy Xiranite Chubby Lung</span>, or <strong>8.777</strong>/min.</p><p>Recommended production plan, with baseline 14.75 batteries, 12 Pyrrolite Part, 24 Heavy Xiranite:</p><p>Phase one: <strong>1</strong> full-rate <span class="mark-green">Xiranite Chubby Lung</span> line.</p><p>Phase two: <strong>1.5</strong> full-rate <span class="mark-sky_blue">Heavy Xiranite Chubby Lung</span> lines.</p><p><span class="mark-grey"><em>P.S. In phase two, 1.5 Heavy Xiranite Chubby Lung lines consume 180 Cuprium Ore/min. Adding the two-Pyrrolite/two-Heavy-Xiranite lines&#39; 360/min exceeds ore output. Four solutions:</em></span></p><p><span class="mark-grey"><em>1. Ignore it: every line using Cuprium slows to 94.44%. Risk: depending on the line&#39;s mode, the Pyrrolite module may block Acridgen and stop producing.</em></span></p><p><span class="mark-grey"><em>2. Close one Pyrrolite module&#39;s Cuprium output feeding Cuprium Gas production. The same risk remains.</em></span></p><p><span class="mark-grey"><em>3. Close one Heavy Xiranite Chubby Lung line&#39;s Cuprium Ore output, reducing production from 9/min to 7.5/min. Event token output is (100<em>9600</em>6+200<em>10800</em>7.5)/10＝2196000＞2180800, still enough to clear the shop.</em></span></p><p><span class="mark-grey"><em>4. Building on 3, if you fear small capacity losses causing insufficient tokens, temporarily add modules consuming stored reserves.</em></span></p><p><span class="mark-red">Plan 3:</span> (Exchange only event products for vouchers.)</p><p>On top of the original line, phase one must produce 19545600/100=<strong>195456</strong> <span class="mark-green">Xiranite Chubby Lung</span>, or <strong>19.390</strong>/min. Phase two must still produce 21988800/200=<strong>109944</strong> <span class="mark-sky_blue">Heavy Xiranite Chubby Lung</span>, or <strong>10.901</strong>/min. (With 0.25 stacking to 0.5: phase two still requires 25444800/200=127224 <span class="mark-sky_blue">Heavy Xiranite Chubby Lung</span>, or 11.78/min.)</p><p>Recommended plan, with baseline 14.75 batteries and 24 Heavy Xiranite:</p><p>Phase one: <strong>3.232</strong> full-rate <span class="mark-green">Xiranite Chubby Lung</span> lines.</p><p>Phase two: 1.817 full-rate <span class="mark-sky_blue">Heavy Xiranite Chubby Lung</span> lines (1.963).</p><p><span class="mark-red">Plan 4:</span> (Rebel! Prioritize exchanging Pyrrolite Part, Heavy Xiranite, and SC Wuling Battery.)</p><p>With the 1.4–1.5 low-effort factory, 14.75 batteries + 18 Pyrrolite Part + 24 Heavy Xiranite, with 3 batteries used for power, phase one still needs <strong>-48624</strong> <span class="mark-green">Xiranite Chubby Lung</span>, or <strong>-5.065</strong>/min; phase two still needs <strong>-27351</strong> <span class="mark-sky_blue">Heavy Xiranite Chubby Lung</span>, or <strong>-2.5325</strong>/min.</p><p>Recommended production plan: <span class="mark-red"><strong>(Are you even playing??? Not recommended!!!)</strong></span></p><p><span class="mark-grey"><em>P.S. Why leave Xiranite and Cuprium unused? These are merely relatively easy plans to implement. What if you want perfect use of every resource?</em></span><span class="mark-orange"><em>Leave it to our great adaptive production lines, of course!</em></span></p><p><span id="source-block-53ZUn1aG2hgB3KMJjCb5sb"></span></p><span class="logistics-source-anchor" id="蓝图" aria-hidden="true"></span><span class="logistics-source-anchor" id="blueprints-continuously-updated" aria-hidden="true"></span><span class="logistics-source-anchor" id="蓝图-持续更新" aria-hidden="true"></span><h2 id="blueprints" tabindex="-1">Blueprints <a class="header-anchor" href="#blueprints" aria-label="Permalink to &quot;Blueprints&quot;">​</a></h2><p>Official small Chubby Lung: EF01eaA7oaeAa4A6ioAi8</p><p>Official large Chubby Lung: EF018OI3eO8IO1Aa4UI73</p><p>Half-rate small Chubby Lung: EF01u28IU2u820ei4AoOU</p><p>Half-rate large Chubby Lung: EF013Eou7E3oEa9IO0579</p><p>Half-rate small Chubby Lung (refining): EF015i2O1i52iu92OeIoe</p><p>Half-rate large Chubby Lung (refining): EF01A67iu6A76Ee169ieO</p><p>Full-rate large Chubby Lung: EF018OI3eO8IO1A63UI73</p><p>Extremely compressed 9/min large Chubby Lung: EF01u28IU2u820eEeAoOU</p><p><span class="mark-grey"><em>Except the official large Chubby Lung blueprint, which needs external Xiragen, the others only need water, Inergen, and a Sewage conduit (Water Treatment Unit).</em></span></p><p>Ko鸟&#39;s personal modular blueprints:</p><p>[A] Two solidifying units: EF015i2O1i52iu9OAeIoe</p><p>[B] 12 large Chubby Lung packaging: EF01u28IU2u820eUEAoOU</p><p>[C] Four-core gas reaction: EF01ao605oa6oA41aoe5e</p><p>[D] Two gasifying units for Cuprium Gas: EF018OI3eO8IO1A66UI73</p><p>2A+1B+0.5C+1D=12/m Heavy Xiranite Chubby Lung; input 24+12+60=96 Xiragen, 66240 Cuprium.</p><blockquote><p>Translation note: “Cuprium-based medicine” means the premium products Jincao Tea or Yazhen Syringe [A]; the short recipe label here does not distinguish them. Medal and event titles without an exact localization match remain descriptive. The source arithmetic, negative requirements, 8.777/10.901 rates, and final “66240” are retained without silently repairing apparent inconsistencies.</p></blockquote></div>',1)])])}const h=a(r,[["render",t]]);export{g as __pageData,h as default};
